_BOUNDARIES = (0.125, 0.15625, 0.1875, 0.21875, 0.25, 0.3125, 0.375, 0.4375, 0.5, 0.625, 0.75, 0.875, 1.0, 1.25, 1.5, 1.75, 2.0, 2.5, 3.0, 3.5, 4.0, 5.0, 6.0, 7.0, 8.0, 10.0)


def _add2(x, y):
    high = x[0] + y[0]
    recovered = high - x[0]
    error = (x[0] - (high - recovered)) + (y[0] - recovered)
    return high, error + (x[1] + y[1])


def _multiply_scalar(x, y):
    high = x[0] * y
    return high, fp32_fma(x[1], y, fp32_fma(x[0], y, -high))


def fp32_native_tanh(values):
    if not torch.compiler.is_compiling() and not torch.jit.is_tracing():
        if (values.device.type != 'cpu' or values.dtype != torch.float32
                or not values.numel() or not torch.isfinite(values).all()):
            raise ValueError('Tanh diagnostic requires nonempty finite CPU FP32 inputs')
    magnitude = values.abs()
    core = torch.minimum(magnitude, torch.full_like(values, 10.))
    # Equivalent to the shader's masked exponent/top-mantissa interval index,
    # using exact FP32 comparison boundaries and standard ONNX operations.
    interval = torch.zeros_like(values, dtype=torch.int64)
    for boundary in _BOUNDARIES:
        interval = interval + (core >= torch.full_like(values, boundary)).to(torch.int64)
    table = torch.tensor(_COEFFICIENTS, dtype=torch.float32)
    coefficient = table[interval, 6]
    pair = coefficient[..., 0], coefficient[..., 1]
    for power in range(5, -1, -1):
        coefficient = table[interval, power]
        pair = _add2(_multiply_scalar(pair, core), (coefficient[..., 0], coefficient[..., 1]))
    result = pair[0] + pair[1]
    result = torch.where(magnitude >= torch.full_like(values, 10.), torch.ones_like(values), result)
    result = torch.where(values < 0, -result, result)
    return torch.where(values == 0, values, result)
